const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const banamepePoint = ee.Geometry.Point([140.3, -6.2]); // Approximate location near Banamepe along Digul River
  const region = banamepePoint.buffer(5000); // 5km buffer around the point

  // Time periods for comparison (November of each year)
  const startDate1 = '2002-11-01';
  const endDate1 = '2002-11-30';
  const startDate2 = '2019-11-01';
  const endDate2 = '2019-11-30';

  // 2. Data Acquisition - MODIS Vegetation Continuous Fields (Tree Cover %)
  const modisVCF = ee.ImageCollection('MODIS/006/MOD44B');

  const forest2002 = modisVCF
    .filterDate(startDate1, endDate1)
    .filterBounds(region)
    .select('Percent_Tree_Cover');

  const forest2019 = modisVCF
    .filterDate(startDate2, endDate2)
    .filterBounds(region)
    .select('Percent_Tree_Cover');

  // Check collection sizes
  const count2002 = forest2002.size().getInfo();
  const count2019 = forest2019.size().getInfo();

  print(`2002 Images: ${count2002}, 2019 Images: ${count2019}`);

  if (count2002 === 0 || count2019 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Get mean images for each period
  const img2002 = forest2002.mean();
  const img2019 = forest2019.mean();

  // 3. Processing - Calculate forest cover statistics
  const stats2002 = img2002.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = img2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const cover2002 = stats2002.get('Percent_Tree_Cover').getInfo();
  const cover2019 = stats2019.get('Percent_Tree_Cover').getInfo();

  // Check for valid pixels
  const pixelCount2002 = img2002.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('Percent_Tree_Cover').getInfo();

  const pixelCount2019 = img2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('Percent_Tree_Cover').getInfo();

  print(`2002 Forest Cover: ${cover2002?.toFixed(1)}%, Pixels: ${pixelCount2002}`);
  print(`2019 Forest Cover: ${cover2019?.toFixed(1)}%, Pixels: ${pixelCount2019}`);

  if (pixelCount2002 === 0 || pixelCount2019 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (cover2002 === null || cover2019 === null || 
      isNaN(cover2002) || isNaN(cover2019) ||
      cover2002 < 0 || cover2002 > 100 ||
      cover2019 < 0 || cover2019 > 100) {
    print("<answer>C3</answer>");
    return;
  }

  const change = cover2019 - cover2002;
  print(`Forest Change: ${change.toFixed(1)}%`);

  // If forest cover decreased by more than 1% (meaningful change)
  if (change < -1) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
